/* db-view-vs-join 엔진 — 코드 JOIN과 Database View가 같은 결과를 내는 걸 보이고,
   마스터 누락 시 inner join이 행을 떨어뜨리는 것, View Field 축소가 구조 계약임을 시연.
   골격 계약: .dvj-seg(상태 토글) · #dvjFields · #dvjBody · #dvjHead · #dvjStatus.
   config: window.DVJ_CFG = { perfRows:[{concert_id,perf_no,perf_date}],
            master:{C001:{artist,venue,...}} (마스터에서 붙는 필드 맵 · 문자열이면 artist 하나로 취급),
            extraRow:{...}(마스터 누락 상태에서 추가), baseFields:[{key,label}], narrowDrop:'artist' }.
   높이: _autoheight.js. */
(function () {
  var CFG = window.DVJ_CFG || {};
  var state = 'normal';   // normal | missing | narrow
  var segEl = document.querySelector('.dvj-seg');
  var fieldsEl = document.getElementById('dvjFields');
  var headEl = document.getElementById('dvjHead');
  var bodyEl = document.getElementById('dvjBody');
  var statusEl = document.getElementById('dvjStatus');
  var STATES = [{ k: 'normal', l: '정상' }, { k: 'missing', l: '마스터 누락(C999)' }, { k: 'narrow', l: '필드 축소' }];

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }

  function fields() {
    return CFG.baseFields.filter(function (f) { return !(state === 'narrow' && f.key === CFG.narrowDrop); });
  }
  function sourceRows() {
    var rows = CFG.perfRows.slice();
    if (state === 'missing' && CFG.extraRow) rows = rows.concat([CFG.extraRow]);
    return rows;
  }
  // inner join: zconcert 마스터가 있는 행만 결과로 남는다.
  // 짝 없는 행을 빈칸으로 남겨 두면 outer join 화면처럼 보이므로 결과에서 실제로 제거하고,
  // 무엇이 빠졌는지는 표 밖(상태문)에서 밝힌다.
  // 마스터에서 붙는 필드는 cfg가 정한다(문자열이면 artist 하나로 취급 — 구버전 cfg 호환)
  function masterOf(id) {
    var m = CFG.master[id];
    if (m == null) return null;
    return (typeof m === 'string') ? { artist: m } : m;
  }
  function joinRows() {
    var kept = [], dropped = [];
    sourceRows().forEach(function (c) {
      var m = masterOf(c.concert_id);
      var row = { concert_id: c.concert_id, perf_no: c.perf_no, perf_date: c.perf_date };
      CFG.baseFields.forEach(function (f) {
        if (!(f.key in row)) row[f.key] = (m && m[f.key] != null) ? m[f.key] : '';
      });
      if (m) kept.push(row); else dropped.push(row);
    });
    return { kept: kept, dropped: dropped };
  }

  function renderSeg() {
    segEl.innerHTML = STATES.map(function (s) {
      return '<button type="button" data-k="' + s.k + '" aria-pressed="' + (s.k === state ? 'true' : 'false') + '">' + esc(s.l) + '</button>';
    }).join('');
  }
  function renderFields() {
    fieldsEl.innerHTML = CFG.baseFields.map(function (f) {
      var gone = state === 'narrow' && f.key === CFG.narrowDrop;
      return '<span class="dvj-field' + (gone ? ' gone' : '') + '">' + esc(f.key) + '</span>';
    }).join('');
  }
  function renderResult() {
    var fs = fields();
    headEl.innerHTML = fs.map(function (f) { return '<th>' + esc(f.label) + '</th>'; }).join('');
    bodyEl.innerHTML = joinRows().kept.map(function (r) {
      return '<tr>' + fs.map(function (f) {
        return '<td>' + esc(r[f.key]) + '</td>';
      }).join('') + '</tr>';
    }).join('');
  }
  function renderStatus() {
    var jr = joinRows(), kept = jr.kept.length;
    if (state === 'missing') {
      var lost = jr.dropped.map(function (r) { return esc(r.concert_id + ' · ' + r.perf_no + ' · ' + r.perf_date); }).join(', ');
      statusEl.className = 'dvj-status warn';
      statusEl.innerHTML = '⚠️ 원본 zperf에는 <b>' + (lost || '마스터 없는 회차') + '</b> 행이 있지만 zconcert에 그 공연이 없어 <b>inner join에서 빠집니다</b>' +
        ' — 위 표에 그 행은 아예 없습니다(결과 <b>' + kept + '행</b>). 빠진 행까지 보려면 코드의 LEFT OUTER JOIN.';
    } else if (state === 'narrow') {
      statusEl.className = 'dvj-status';
      statusEl.innerHTML = 'View Field에서 <b>artist</b>를 빼면 결과 컬럼이 줄어듭니다. View Field는 외부 프로그램의 <b>구조 계약</b> — 함부로 빼면 쓰던 프로그램이 깨집니다.';
    } else {
      statusEl.className = 'dvj-status';
      statusEl.innerHTML = '✅ 코드 JOIN과 Database View가 <b>같은 ' + kept + '행</b>을 냅니다. 결과는 같고 <b>정의 위치</b>만 다릅니다(코드 vs DDIC).';
    }
  }
  function render() { renderSeg(); renderFields(); renderResult(); renderStatus(); }

  segEl.addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; state = b.getAttribute('data-k'); render(); });
  render();
})();

=====FILE:C:\SAP\sap-dev-academy\embeds\_engine\field-curtain.js=====
/* field-curtain 엔진 — Projection View 필드 선택을 켜고 끄면 결과 컬럼이 바뀐다. key 필드 경고·기술필드 일괄 숨김·ABAP 구조 미리보기.
   골격 계약: #fcFields · [data-tech] · [data-all] · #fcHead · #fcBody · #fcStruct · #fcFb.
   config: window.FC_CFG = { table, structName, fields:[{key,label,tech,isKey}], rows:[{}] }. 높이: _autoheight.js. */
(function () {
  var CFG = window.FC_CFG || { fields: [], rows: [] };
  var sel = {};
  CFG.fields.forEach(function (f) { sel[f.key] = true; });   // 초기: 전체 노출

  var fieldsEl = document.getElementById('fcFields');
  var headEl = document.getElementById('fcHead');
  var bodyEl = document.getElementById('fcBody');
  var structEl = document.getElementById('fcStruct');
  var fbEl = document.getElementById('fcFb');

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }
  function selected() { return CFG.fields.filter(function (f) { return sel[f.key]; }); }

  function renderFields() {
    fieldsEl.innerHTML = CFG.fields.map(function (f) {
      var tag = f.isKey ? '<span class="tag key">KEY</span>' : (f.tech ? '<span class="tag tech">기술</span>' : '');
      return '<label class="fc-field' + (sel[f.key] ? '' : ' off') + '"><input type="checkbox" data-k="' + f.key + '"' + (sel[f.key] ? ' checked' : '') + '>' +
        '<span>' + esc(f.key) + '</span>' + tag + '</label>';
    }).join('');
  }
  function renderResult() {
    var fs = selected();
    headEl.innerHTML = fs.map(function (f) { return '<th>' + esc(f.key) + '</th>'; }).join('');
    bodyEl.innerHTML = CFG.rows.map(function (r) {
      return '<tr>' + fs.map(function (f) { return '<td>' + esc(r[f.key]) + '</td>'; }).join('') + '</tr>';
    }).join('');
  }
  function renderStruct() {
    var fs = selected();
    var nm = CFG.structName || 'ts_basic';
    var tbl = CFG.table || '';
    // 컴포넌트마다 타입을 붙인다 — 타입 없이 적으면 그대로 옮겨 쓸 수 없는 코드가 된다
    structEl.querySelector('pre').innerHTML =
      '<span class="kw">TYPES</span>: <span class="kw">BEGIN OF</span> ' + esc(nm) + ',\n' +
      (fs.length ? fs.map(function (f) {
        return '         ' + esc(f.key) + ' <span class="kw">TYPE</span> ' + esc(tbl) + '-' + esc(f.key);
      }).join(',\n') + ',\n' : '') +
      '       <span class="kw">END OF</span> ' + esc(nm) + '.';
  }
  function renderFb() {
    var fs = selected();
    // 경고에 쓰는 key 이름은 cfg에서 뽑는다(하드코딩하면 다른 테이블을 쓰는 레슨에서 엉뚱한 필드를 지목한다)
    var keyMissing = CFG.fields.filter(function (f) { return f.isKey && !sel[f.key]; });
    var techShown = CFG.fields.filter(function (f) { return f.tech && sel[f.key]; }).length;
    if (!fs.length) { fbEl.className = 'fc-fb warn'; fbEl.innerHTML = '필드를 하나 이상 노출해야 합니다.'; return; }
    if (keyMissing.length) {
      fbEl.className = 'fc-fb warn';
      fbEl.innerHTML = '⚠️ 업무 화면에서 행을 식별할 <b>key 필드(' +
        keyMissing.map(function (f) { return esc(f.key); }).join(', ') + ')</b>는 남겨야 합니다.';
      return;
    }
    fbEl.className = 'fc-fb';
    fbEl.innerHTML = '노출 ' + fs.length + ' / ' + CFG.fields.length + '개. ' +
      (techShown ? '기술 필드(' + techShown + '개)가 아직 노출 중 — Projection View는 안 봐도 되는 컬럼을 줄이는 데 유용합니다.' : '✅ 기술 필드를 모두 가렸습니다 — 업무에 필요한 컬럼만 깔끔하게 노출됩니다.');
  }
  function render() { renderFields(); renderResult(); renderStruct(); renderFb(); }

  fieldsEl.addEventListener('change', function (e) {
    var cb = e.target.closest('input[data-k]'); if (!cb) return;
    sel[cb.getAttribute('data-k')] = cb.checked; render();
  });
  var techBtn = document.querySelector('[data-tech]');
  if (techBtn) techBtn.addEventListener('click', function () { CFG.fields.forEach(function (f) { if (f.tech) sel[f.key] = false; }); render(); });
  var allBtn = document.querySelector('[data-all]');
  if (allBtn) allBtn.addEventListener('click', function () { CFG.fields.forEach(function (f) { sel[f.key] = true; }); render(); });

  render();
})();

=====FILE:C:\SAP\sap-dev-academy\embeds\_engine\f4-help-flow.js=====
/* f4-help-flow 엔진 — 입력 필드에 F4 → Help View 결과 팝업 → 행 선택 시 key가 화면으로 복귀.
   토글: 설명 누락(보조 테이블 outer → primary 유지·설명 빈칸), Export OFF(선택해도 복귀 안 함).
   골격 계약: #f4Input · [data-f4] · .f4-pop · #f4PopBody · [data-miss] · [data-exp] · #f4Status.
   config: window.F4_CFG = { field, cols:[{key,label}], rows:[{concert_id,name,artist,venue}], missId,
            helpView(Help View 이름)·helpCols(팝업이 보여 주는 컬럼 안내) }. 높이: _autoheight.js. */
(function () {
  var CFG = window.F4_CFG || { rows: [], cols: [] };
  var val = '', miss = false, exp = false;
  var inputEl = document.getElementById('f4Input');
  var popEl = document.querySelector('.f4-pop');
  var popBody = document.getElementById('f4PopBody');
  var statusEl = document.getElementById('f4Status');
  var missBtn = document.querySelector('[data-miss]');
  var expBtn = document.querySelector('[data-exp]');

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }

  function descOf(r) { return (miss && r.concert_id === CFG.missId) ? '' : r.name; }

  function renderInput() {
    inputEl.textContent = val || '(비어 있음)';
    inputEl.classList.toggle('empty', !val);
  }
  function renderPop() {
    popBody.innerHTML = CFG.rows.map(function (r) {
      var d = descOf(r);
      return '<tr data-id="' + r.concert_id + '"><td>' + esc(r.concert_id) + '</td>' +
        '<td class="' + (d ? '' : 'blank') + '">' + (d ? esc(d) : '(공연명 없음)') + '</td>' +
        '<td>' + esc(r.artist) + '</td><td>' + esc(r.venue) + '</td></tr>';
    }).join('');
  }
  function setStatus(cls, html) { statusEl.className = 'f4-status' + (cls ? ' ' + cls : ''); statusEl.innerHTML = html; }

  document.querySelector('[data-f4]').addEventListener('click', function () {
    renderPop(); popEl.classList.add('open');
    // 객체명·컬럼은 cfg에서 — 하드코딩하면 팝업에 없는 컬럼을 안내하게 된다
    setStatus('', '🔍 Help View <b>' + esc(CFG.helpView || 'ZHV_CONCERT') + '</b>가 ' +
      esc(CFG.helpCols || '코드·공연명·아티스트·공연장') + '을 보여 줍니다. 한 행을 고르세요.');
  });
  popEl.addEventListener('click', function (e) {
    if (e.target.closest('.x')) { popEl.classList.remove('open'); return; }
    var tr = e.target.closest('tr[data-id]'); if (!tr) return;
    var id = tr.getAttribute('data-id');
    popEl.classList.remove('open');
    if (exp) {
      setStatus('warn', '⚠️ <b>' + id + '</b>을(를) 골랐지만 화면 필드가 그대로입니다 — Export Parameter가 없으면 선택값이 안 돌아옵니다. (F4 목록 표시와 값 복귀는 별도 설정)');
      return;
    }
    val = id; renderInput();
    setStatus('ok', '✅ 사용자는 <b>설명</b>을 보고 골랐지만, 화면 필드에는 <b>key(' + id + ')</b>가 돌아왔습니다. F4 = DDIC↔화면 데이터 흐름.');
  });
  if (missBtn) missBtn.addEventListener('click', function () {
    miss = !miss; missBtn.setAttribute('aria-pressed', miss ? 'true' : 'false');
    if (popEl.classList.contains('open')) renderPop();
    if (miss) setStatus('', 'ℹ️ 보조 설명 테이블에서 <b>' + CFG.missId + '</b>행을 뺐습니다. Help View는 <b>primary table 보존(outer)</b>이라 ' + CFG.missId + '는 목록에 남고 <b>설명만 비어</b> 보입니다. (F4 다시 눌러 확인)');
  });
  if (expBtn) expBtn.addEventListener('click', function () {
    exp = !exp; expBtn.setAttribute('aria-pressed', exp ? 'true' : 'false');
    setStatus('', exp ? 'Export Parameter를 <b>껐습니다</b>. 이제 행을 골라도 화면에 값이 안 돌아옵니다 — F4 다시 눌러 확인.' : 'Export Parameter를 켰습니다. 선택한 key가 화면으로 돌아옵니다.');
  });

  renderInput();
  setStatus('', '입력 필드 옆 <b>F4</b>를 눌러 공연을 검색해 보세요.');
})();

=====FILE:C:\SAP\sap-dev-academy\embeds\_engine\fk-maintenance-gate.js=====
/* fk-maintenance-gate 엔진 — Foreign Key를 켜고 끄며 유지보수 화면에서 input check가 잘못된 코드를 막는 걸 시연.
   FK ON: zconcert에 없는 concert_id 거부(input check) · FK OFF: 무엇이든 통과(orphan 위험).
   골격 계약: [data-fk] · .fkm-line · .fkm-halls · #fkmBody · #fkmStatus.
   config: window.FKM_CFG = { masters:{C001:'안유진',...}, options:['C001','C002','C999'] }. 높이: _autoheight.js. */
(function () {
  var CFG = window.FKM_CFG || { masters: {}, options: [] };
  var fk = true, rows = [], seq = 0;
  var fkBtn = document.querySelector('[data-fk]');
  var lineEl = document.querySelector('.fkm-line');
  var hallsEl = document.querySelector('.fkm-halls');
  var bodyEl = document.getElementById('fkmBody');
  var statusEl = document.getElementById('fkmStatus');

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }
  function valid(h) { return Object.prototype.hasOwnProperty.call(CFG.masters, h); }

  function renderHalls() {
    var btns = CFG.options.map(function (h) {
      return '<button class="fkm-hall' + (valid(h) ? '' : ' bad') + '" type="button" data-h="' + h + '">' + esc(h) + (valid(h) ? '' : ' (없음)') + '</button>';
    }).join('');
    hallsEl.innerHTML = '<span class="lbl">회차 유지보수: concert_id 입력 →</span>' + btns;
  }
  function renderRows() {
    if (!rows.length) { bodyEl.innerHTML = '<tr><td colspan="3" class="fkm-empty">아직 추가된 행이 없습니다.</td></tr>'; return; }
    bodyEl.innerHTML = rows.map(function (r) {
      var name = CFG.masters[r.concert_id];
      var orphan = !name;
      return '<tr class="' + (orphan ? 'orphan' : '') + '"><td>' + esc(r.perf_key) + '</td>' +
        '<td class="' + (orphan ? 'bad' : '') + '">' + esc(r.concert_id) + '</td>' +
        '<td>' + (name ? esc(name) : '<span class="bad">⚠ 참조 없음(orphan)</span>') + '</td></tr>';
    }).join('');
  }
  function setStatus(cls, html) { statusEl.className = 'fkm-status' + (cls ? ' ' + cls : ''); statusEl.innerHTML = html; }

  function addHall(h) {
    if (fk && !valid(h)) {
      setStatus('err', '✗ <b>input check 거부</b> — <b>' + esc(h) + '</b>은(는) zconcert(Check Table)에 없는 공연 코드입니다. Foreign Key가 잘못된 입력을 막았습니다.');
      return;
    }
    seq++; rows.push({ perf_key: ('00' + seq).slice(-3) + '회차', concert_id: h });
    renderRows();
    if (valid(h)) setStatus('ok', '✅ <b>' + esc(h) + '</b>(' + esc(CFG.masters[h]) + ') 회차 저장. Foreign Key가 있으면 존재하는 코드만 통과합니다.');
    else setStatus('warn', '⚠️ FK가 꺼져 <b>' + esc(h) + '</b>가 그대로 저장됐습니다 — zconcert에 없는 <b>orphan</b>(참조 무결성 깨짐). 그래서 Foreign Key가 설계의 기준입니다.');
  }

  function render() {
    fkBtn.setAttribute('aria-pressed', fk ? 'true' : 'false');
    fkBtn.textContent = fk ? 'Foreign Key: ON 🔗' : 'Foreign Key: OFF ✂';
    lineEl.classList.toggle('on', fk);
    lineEl.innerHTML = fk ? '──FK──▶<span class="lab">check</span>' : '·· 끊김 ··<span class="lab">no check</span>';
    renderHalls(); renderRows();
  }

  hallsEl.addEventListener('click', function (e) { var b = e.target.closest('.fkm-hall'); if (!b) return; addHall(b.getAttribute('data-h')); });
  fkBtn.addEventListener('click', function () { fk = !fk; render(); setStatus('', fk ? 'Foreign Key를 켰습니다 — 이제 zconcert에 없는 코드는 input check가 막습니다.' : 'Foreign Key를 껐습니다 — 이제 어떤 코드든 통과합니다(orphan 위험).'); });

  render();
  setStatus('', '<b>Foreign Key</b>를 켠 채 <b>C999(없음)</b>를 입력해 보세요. input check가 막습니다. FK를 끄면 통과합니다.');
})();

=====FILE:C:\SAP\sap-dev-academy\embeds\_engine\sm30-gate-checklist.js=====
/* sm30-gate-checklist 엔진 — SM30 유지보수 화면이 열리려면 모든 조건(게이트)이 맞아야 함을 시연.
   게이트: 테이블 활성화 → 유지보수 허용 → TMG 생성 → 권한 OK. SM30 실행 시 하나라도 빠지면 막힌다.
   골격 계약: #sgcGates · .sgc-pipe · [data-run] · #sgcStatus · #sgcGrid(.sgc-tbl).
   config: window.SGC_CFG = { gates:[{key,label,sub}], gridCols:[{key,label}], gridRows:[{}] }. 높이: _autoheight.js. */
(function () {
  var CFG = window.SGC_CFG || { gates: [], gridCols: [], gridRows: [] };
  var on = {};
  CFG.gates.forEach(function (g) { on[g.key] = false; });
  var gatesEl = document.getElementById('sgcGates');
  var pipeEl = document.querySelector('.sgc-pipe');
  var statusEl = document.getElementById('sgcStatus');
  var gridEl = document.getElementById('sgcGrid');

  function esc(s) { return String(s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); }
  function firstOff() { for (var i = 0; i < CFG.gates.length; i++) if (!on[CFG.gates[i].key]) return CFG.gates[i]; return null; }

  function renderGates() {
    gatesEl.innerHTML = CFG.gates.map(function (g) {
      return '<label class="sgc-gate' + (on[g.key] ? ' on' : '') + '"><input type="checkbox" data-k="' + g.key + '"' + (on[g.key] ? ' checked' : '') + '>' +
        '<span class="g-name">' + esc(g.label) + '</span><span class="g-sub">' + esc(g.sub || '') + '</span></label>';
    }).join('');
  }
  function renderPipe() {
