      return '<button type="button" data-v="' + it.v + '" aria-pressed="' + (it.v === active ? 'true' : 'false') + '">' + esc(it.l) + '</button>';
    }).join('');
  }
  function render() {
    saveBtn.disabled = saved;
    savedEl.textContent = saved ? '✓ ZPERF에 C999 001회차 저장됨' : '';
